function viewBox(){const b=map.getBounds().pad(.1);return[b.getSouth(),b.getWest(),b.getNorth(),b.getEast()]}
function containsBox(a,b){return a[0]<=b[0]&&a[1]<=b[1]&&a[2]>=b[2]&&a[3]>=b[3]}
function scheduleNational(){clearTimeout(nationalTimer);if(config&&map.getZoom()>=4&&$('#show-pk').checked)nationalTimer=setTimeout(loadNationalView,650)}
async function loadNationalView(force=false){if(!config||map.getZoom()<4)return;if(nationalRunning){nationalPending=true;return}const bbox=viewBox(),countries=countriesInBounds(bbox).filter(c=>force||!coveredRegions.some(r=>r.country===c&&r.detail>=(map.getZoom()>=9?1:0)&&containsBox(r.bbox,bbox)));if(!countries.length)return;nationalRunning=true;const token=++nationalToken;$('#pk-status').textContent='Chargement des bornes nationales…';const results=await Promise.allSettled(countries.map(async country=>{const data=await countryIndex.bounds(country,bbox,map.getZoom());addData(data);if(data.complete)coveredRegions.push({country,bbox,detail:map.getZoom()>=9?1:0});return data}));renderMap();updateCoverage();const warnings=[];for(let i=0;i<results.length;i++){const r=results[i];if(r.status==='rejected')warnings.push(countries[i]+' : '+errorText(r.reason));else if(!r.value.complete||r.value.warning)warnings.push(countries[i]+' : '+(r.value.warning||'Zone dense : chargement partiel, zoomez.'))}$('#pk-status').textContent=warnings.length?'Bornes : '+warnings.join(' · '):'Index nationaux prêts · '+Object.entries(countryIndex.manifest?.countries||{}).map(([c,d])=>c+' '+d.count.toLocaleString('fr-FR')).join(' · ');nationalRunning=false;if(nationalPending){nationalPending=false;scheduleNational()}}

const roadLayer=L.layerGroup().addTo(map),pkLayer=L.layerGroup().addTo(map),poiLayer=L.layerGroup().addTo(map),candidateLayer=L.layerGroup().addTo(map),selectionLayer=L.layerGroup().addTo(map);
function message(text,error=false){$('#map-message').textContent=text;$('#map-message').classList.toggle('error',error)}
