function errorText(e){return e?.name==='AbortError'?'Le service a dépassé le délai de réponse.':e.message||'Service indisponible.'}
async function jsonFetch(url,options={},timeout=30000){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),timeout);try{const r=await fetch(url,{...options,signal:controller.signal});if(!r.ok)throw new Error(`Service indisponible (HTTP ${r.status}).`);return await r.json()}finally{clearTimeout(timer)}}
const memoryCache=new Map();
async function nominatim(type,params){const base=config.nominatim.replace(/\/$/,''),url=`${base}/${type}?${new URLSearchParams({...params,format:'jsonv2','accept-language':'fr',addressdetails:'1'})}`;let cached=memoryCache.get(url);try{cached=cached||JSON.parse(sessionStorage.getItem(url)||'null')}catch{}if(cached)return cached;const task=nomQueue.then(async()=>{const wait=1100-(Date.now()-lastNominatim);if(wait>0)await new Promise(r=>setTimeout(r,wait));lastNominatim=Date.now();const data=await jsonFetch(url);memoryCache.set(url,data);try{sessionStorage.setItem(url,JSON.stringify(data))}catch{}return data});nomQueue=task.catch(()=>{});return task}
async function overpass(query){let last;for(const endpoint of config.overpass){try{const j=await jsonFetch(endpoint,{method:'POST',body:new URLSearchParams({data:query})},45000);if(j.remark)throw new Error('Réponse géographique incomplète : '+j.remark);if(!Array.isArray(j.elements))throw new Error('Réponse géographique invalide.');return j}catch(e){last=e}}throw last}
function addData(data){const pm=new Map(pois.map(p=>[p.id,p]));for(const p of data.pois||[])pm.set(p.id,p);pois=[...pm.values()];const rm=new Map(roads.map(p=>[p.id,p]));for(const r of data.roads||[])rm.set(r.id,r);roads=[...rm.values()];const km=new Map(records.map(p=>[p.id,p]));for(const p of data.pks||[]){const old=km.get(p.id);km.set(p.id,p.roadUnknown&&old&&!old.roadUnknown?{...p,road:old.road,roadUnknown:false,status:old.status}:p)}records=[...km.values()]}
function digestOSM(j,country){const out={pois:[],roads:[],pks:[]};const retrieved=new Date().toISOString().slice(0,10);for(const e of j.elements){const t=e.tags||{};if(['motorway','trunk'].includes(t.highway)&&e.geometry){out.roads.push({id:`way/${e.id}`,road:t.ref||t.name||'Grand axe',geometry:e.geometry.map(p=>[p.lat,p.lon])});continue}const p=osmPoint(e);if(!p)continue;p.retrieved=retrieved;if(t.highway==='milestone'){const value=parsePK(t.distance??t.pk??'');if(Number.isFinite(value)&&t.ref&&country)out.pks.push({...p,id:'osm:'+p.id,country,road:t.ref,value,unit:'PK',source:'OpenStreetMap — borne renseignée, non certifiée',status:'Donnée communautaire',direction:t.direction||t.carriageway_ref||'',retrieved});continue}out.pois.push(p)}return out}
function inSnapshot(p,margin=0){return Object.values(snapshot?.cities||{}).find(c=>{const b=c.bbox,dy=margin/111000,dx=margin/(111000*Math.cos(p.lat*Math.PI/180));return b&&p.lat>=b[0]+dy&&p.lat<=b[2]-dy&&p.lon>=b[1]+dx&&p.lon<=b[3]-dx})}
function clearSelection(){selectionToken++;selection=null;selectedPOIs=[];selectionLayer.clearLayers();$('#selection').hidden=true;$('#point-preview').hidden=true;}
function renderMap(){const bounds=map.getBounds(),z=map.getZoom();roadLayer.clearLayers();pkLayer.clearLayers();poiLayer.clearLayers();let visiblePK=0,visiblePOI=0;const visible=p=>bounds.contains([p.lat,p.lon]);
if(z>=10&&$('#show-roads').checked){for(const r of roads){if(!r.geometry?.length)continue;L.polyline(r.geometry,{color:'#196aa3',weight:z<12?3:5,opacity:.7,interactive:false}).addTo(roadLayer)}}
if(z>=4&&$('#show-pk').checked){const interval=markerInterval(z),taken=[];const inView=records.filter(p=>visible(p)&&(z>=10||p.value>=interval)&&Math.abs(p.value/interval-Math.round(p.value/interval))<.00001).sort((a,b)=>({motorway:0,national:1,other:2}[roadClass(a.road,a.country)]-({motorway:0,national:1,other:2}[roadClass(b.road,b.country)]))||a.value-b.value);
for(const p of inView){const xy=map.latLngToContainerPoint([p.lat,p.lon]),w=String(p.value).length*7+14;const rect=[xy.x-w/2,xy.y-13,xy.x+w/2,xy.y+13];if(taken.some(r=>rect[0]<r[2]+5&&rect[2]>r[0]-5&&rect[1]<r[3]+5&&rect[3]>r[1]-5))continue;taken.push(rect);const label=`${p.road} · ${p.unit||'PK'} ${p.value}`;L.marker([p.lat,p.lon],{title:label,icon:L.divIcon({className:'pk-number '+roadClass(p.road,p.country),html:esc(p.value),iconSize:[w,26]})}).bindTooltip(esc(label)).on('click',()=>selectPoint(p)).addTo(pkLayer);visiblePK++}}
if(z>=14&&$('#show-poi').checked){for(const p of pois.filter(visible).slice(0,500)){L.marker([p.lat,p.lon],{icon:L.divIcon({className:'poi-pin',iconSize:[10,10]}),keyboard:true,title:pointName(p)}).bindTooltip(esc(pointName(p))).on('click',()=>selectPoint({...p,kind:'Repère géographique documenté (point ou centre cartographique)'})).addTo(poiLayer);visiblePOI++}}
$('#zoom-label').textContent=`Zoom ${z}`;$('#data-count').textContent=`${visiblePK} bornes affichées · ${visiblePOI} repères`;$('#pk-map-count').textContent=`${visiblePK} PK / PR`;$('#national-summary').textContent=countryIndex.manifest?'3 pays · '+Object.values(countryIndex.manifest.countries).reduce((n,c)=>n+c.count,0).toLocaleString('fr-FR')+' bornes':'Préparation des index…';}

