async function showCountry(country){if(matchMedia('(max-width:680px)').matches)document.querySelector('.sidebar').classList.add('collapsed');clearSelection();pkToken++;$('#pk-results').replaceChildren();$('#country').value=country;$('#road').value=config.countries[country].example;const regions=Object.keys(countryViews[country]);$('#country-region').innerHTML=regions.map(r=>`<option>${esc(r)}</option>`).join('');$('#country-region').hidden=regions.length===1;$('#country-region').onchange=()=>focusCountryRegion(country,$('#country-region').value);focusCountryRegion(country,regions[0]);$$('[data-country-view]').forEach(b=>b.classList.toggle('active',b.dataset.countryView===country));message('Chargement de la vue nationale…');await countryIndex.overview(country);updateCoverage();renderMap();scheduleNational();message('Bornes réelles espacées sur cette vue. Zoomez pour détailler ou recherchez directement une route et un PK.');}
