function coverageText(country){const c=countryIndex.manifest?.countries[country];return c?`${c.count.toLocaleString('fr-FR')} bornes indexées sur le territoire du pays · ${Object.keys(c.roads).length.toLocaleString('fr-FR')} références de routes. ${country==='DE'?'Autoroutes fédérales, BKG POI-Open, 03/2025.':country==='FR'?'PR IGN BD TOPO : autoroutes, nationales et départementales.':'Bornes IGN/CNIG, péninsule et îles.'} Recherche dans l’index complet, indépendante de la carte affichée. Date de récupération : ${countryIndex.manifest.retrieved}. Les bornes absentes des sources ne sont pas interpolées.`:'Pas d’index préparé pour ce pays.'}

